import traceback
from itertools import islice, cycle

from typing import List, Optional

from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.test_cases import UpgradeTest
from taf.rfrl.csv4all.resources.test_cases.exceptions import IterationFailedError, TestPreconditionFailed, \
    TestFailedOnTeardownError, TestExecutionFailed, RecoveryAttemptFailedError
from taf.rfrl.csv4all.resources.test_cases.csv4all_test import test_logger
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, wrapper_decorator
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError


class SwDownloadTest(UpgradeTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 stop_test_after_fail: bool = False,
                 artifactory_location: Optional[str] = "espoo2", package_suffix: Optional[str] = "A54",
                 l3_call_method: Optional[callable] = None, synchronize_software_on_passive: Optional[bool] = False,
                 activate_sw_at_the_end: Optional[bool] = False, virtualenv_dir: str = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0, software_precheck: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, False, None,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment, sw_build, topology,
                         use_external_storage, download_path, True, stop_test_after_fail,
                         artifactory_location, package_suffix, l3_call_method, synchronize_software_on_passive,
                         virtualenv_dir, None, detailed_console_log, collect_passed_logs=collect_passed_logs)
        self.use_testpackage = True
        self.hwf_migration_check = False
        self.reset_incrementation = False
        self.activate_sw_at_the_end = activate_sw_at_the_end
        self.software_precheck = software_precheck

    def run_test(self):
        try:
            self.run_setup()
            self.execute_test_in_loop()
            if any(nodes_results != "passed" for nodes_results in self.test_results.values()):
                raise TestExecutionFailed()
        except (FatalError, RecoveryAttemptFailedError):
            self.activate_sw_at_the_end = False
            raise
        finally:
            if self.report_to_rp:
                self.report_results()
            self.run_teardown()

    def test_setup(self):
        super(UpgradeTest, self).test_setup()
        self.check_source_and_target_sw()
        self.download_builds_from_wft({node.target_sw for node in self.test_nodes if node.target_sw},
                                      download_candidate=False)
        self.prepare_uboot_scripts()
        self.set_sw_path_for_nodes()
        for node in self.test_nodes:
            self._set_current_logs_dir(node)
            self.remove_hwf_flag(node)
            if self.uboot.uboot_scripts_prepared:
                self.perform_uboot_downgrade_if_needed(node)

    def test(self):
        try:
            self.run_iteration_precondition()
            self.failed_nodes = self.test_operation(None)
        except Exception as e:
            self.stop_test_log_tracing(self.current_logs_dir)
            self.gather_mumin_logs_and_snapshot()
            test_logger("Iteration Failed!", "error")
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

            raise

        self.verify_failed_nodes_after_iteration()

        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    @wrapper_decorator
    def _precondition(self, node):
        self._set_current_logs_dir(node)
        self.check_active_sw(node, node.source_sw)

    def test_operation(self, node):
        self.set_timestamp_reporting_and_kpi()
        self.sw_download_test()
        return self.failed_nodes

    def sw_download_test(self):
        with RobotWrapper("Software Download Test", "kw"):
            for node in self.test_nodes:
                self.download_sw(node)

    @wrapper_decorator
    def download_sw(self, node):
        self._download_sw(node)
        self.summary_operation(node, "download", self.failed_nodes_during_download)

    def _download_sw(self, test_node):
        self._set_current_logs_dir(test_node)
        if self.check_nodes_state_before_operation(test_node):
            self.failed_nodes[test_node.node_alias].update(self.download_sw_operation(test_node))
        else:
            self.gather_mumin_logs_and_snapshot('update')
            self.failed_nodes_during_download = {test_node.node_alias}
        if self.l3_call_method:
            self.l3_call_result = self.execute_l3_call_scenario(test_node)

    @method_decorator()
    def download_sw_operation(self, node):
        operation = "download"
        node.target_sw_path = next(node.iter_target_sw_list)
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.failed_nodes_during_download = self.perform_software_precheck(node)
            self.live_update_precheck(node)
            self.gather_blackbox_and_set_reset_counter(operation)
            node.download_sw()
            self.failed_nodes_during_download.update(self.run_test_verification(node, operation=operation))
            return self.failed_nodes_during_download
        except Exception as e:
            test_logger(e, console=False)
            self.failed_nodes_during_download = {node.node_alias}
            node.btsverify.bts_fault_message += f"\n{str(e)}"
            if "not completed within timeout" in str(e):
                self.restart_admin_connection(node)
                node.wait_till_sw_download_finish()
            return self.failed_nodes_during_download

    @method_decorator()
    def report_results_to_uuf_dashboard(self):
        pass

    @method_decorator()
    def verify_planned_sw(self, node):
        try:
            node.verify_planned_sw()
            return set()
        except WrongSwVersion:
            test_logger(f"Planned SW verification failed for node: {node.node_alias}", "ERROR")
            return {node.node_alias}

    def run_test_verification(self, node, hw_timer: int = None, alarm_timer: int = None, operation: str = None,
                              verify_planned_sw: bool = True, reset_incrementation: bool = False):
        failed_nodes = self.multi_runner.verify_all_nodes(hw_timer, alarm_timer)
        failed_nodes.update(self.multi_runner.verify_mplane())
        if verify_planned_sw:
            failed_nodes.update(self.verify_planned_sw(node))
        failed_nodes.update(self.multi_runner.stop_logs_and_verify_on_all_nodes(f"{self.current_logs_dir}/{operation}",
                                                                                node, reset_incrementation))

        if failed_nodes or not self.passed_logs_gathered:
            self.gather_mumin_logs_and_snapshot()
        return failed_nodes

    @method_decorator()
    def set_sw_path_for_nodes(self):
        for node in self.test_nodes:
            target_sw_paths_list = list(
                islice(cycle(self.wft.target_sw_dict.values()), self.iterations_per_node + 1))
            node.iter_target_sw_list = iter(target_sw_paths_list)
            test_logger(f"{node.node_alias} will use: "
                        f"{','.join([path for path in self.wft.target_sw_dict.values()])}")

    def activate_downloaded_sw(self):
        try:
            for node in self.test_nodes:
                self.setup_admin_connections()
                failed_nodes = self.activate_software(node)
                if failed_nodes:
                    raise TestFailedOnTeardownError
        finally:
            self.teardown_nodes()

    @method_decorator()
    def check_source_and_target_sw(self):
        super().check_source_and_target_sw()
        for node in self.test_nodes:
            try:
                passive_sw = node.get_passive_sw()
            except IndexError:
                test_logger(f"Passive partition is empty on {node.node_alias}")
                continue
            if f"{node.target_sw}T1" in passive_sw or f"{node.target_sw}T2" in passive_sw:
                test_logger(f"Passive SW can't be on T1 or T2 of target software\n"
                            f"Passive SW: {passive_sw}", "WARN")
                try:
                    node.synchronize_software_on_passive(copy_to_passive=0)
                except Exception as e:
                    test_logger(e, "DEBUG")
                    test_logger("Synchronize software on passive partition failed!", "ERROR")
                    raise e

    @method_decorator()
    def activate_software(self, node):
        operation = "update"
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.gather_blackbox_and_set_reset_counter(operation)
            self.add_all_allowed_specific_faults(node)
            node.activate_sw(timeout=self.mplane_access_timeout)
            failed_nodes = self.run_test_verification(node, operation=operation, verify_planned_sw=False,
                                                      reset_incrementation=True)
            return failed_nodes
        except Exception as e:
            failed_nodes = {node.node_alias}
            node.btsverify.bts_fault_message += f"\n{str(e)}"
            if "not completed within timeout" in str(e):
                self.restart_admin_connection(node)
                node.wait_till_sw_download_finish()
            self.exception_handling(operation, e)
            return failed_nodes
        finally:
            self.remove_allowed_alarms_from_nodes(self.nodes, self.all_allowed_specific_faults)

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            if self.activate_sw_at_the_end:
                self.use_testpackage = False
                self.activate_downloaded_sw()
        finally:
            super().test_teardown()

    def perform_software_precheck(self, node):
        if self.software_precheck:
            return super().perform_software_precheck(node)
        return set()
